<script setup lang="ts">
import MoneyInput from './MoneyInput.vue';
import { computed, ref } from 'vue';
import { state, mutate, mutation, today } from '../store.ts';
import { obligations, remaining, billStatus, selfShare, money, type Bill } from '../domain.ts';
import { parseMoney } from '../contracts.ts';
import { fromZonedTime } from '../timezone.ts';
import Icon from './Icon.vue';
import Money from './Money.vue';
import AttachmentPanel from './AttachmentPanel.vue';
import ReceiptBillBreakdown from './ReceiptBillBreakdown.vue';
const props = defineProps<{ billID: string }>();
const emit = defineEmits<{ edit: [bill: Bill]; remove: [bill: Bill] }>();
const bill = computed(() => state.data.splitBills.find(row => row.id === props.billID)!);
const memberID = ref(''), amount = ref(''), accountID = ref(state.data.accounts.find(row => !row.archived)?.id ?? ''), date = ref(today()), reason = ref(''), action = ref('settlement'), error = ref('');
const editable = computed(() => ![...bill.value.settlements, ...bill.value.resolutions].some(event => !event.reversed));
async function save() {
  error.value = '';
  try {
    const member = obligations(bill.value).find(row => row.id === memberID.value); if (!member) throw new Error('Pilih peserta dengan sisa kewajiban.');
    if (parseMoney(amount.value) > remaining(bill.value, member)) throw new Error('Jumlah melebihi sisa kewajiban.');
    if (action.value === 'resolution' && (!reason.value.trim() || !window.confirm('Hapus kewajiban ini? Saldo akun tidak berubah. Piutang yang dihapus menjadi pengeluaran nonkas; utang yang dibebaskan menjadi pemasukan nonkas.'))) return;
    if (await mutate(action.value === 'settlement' ? 'record_split_settlement' : 'record_split_resolution', { ...mutation(), p_split_bill_id: bill.value.id, p_member_id: memberID.value, p_amount: amount.value, p_occurred_at: fromZonedTime(date.value, state.timezone), ...(action.value === 'settlement' ? { p_account_id: accountID.value, p_note: reason.value || null } : { p_reason: reason.value }) })) { amount.value = ''; reason.value = ''; }
  } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Belum tersimpan.'; }
}
async function reverse(eventID: string, version: number, resolution: boolean) { const explanation = window.prompt('Alasan pembatalan (wajib)'); if (!explanation?.trim()) return; await mutate(resolution ? 'reverse_split_resolution' : 'reverse_split_settlement', { ...mutation(), [resolution ? 'p_resolution_id' : 'p_settlement_id']: eventID, p_expected_version: version, p_reason: explanation }); }
async function copy() { try { await navigator.clipboard.writeText(`${bill.value.title}\nTotal ${money(bill.value.total)}; bagian saya ${money(selfShare(bill.value))}\n${obligations(bill.value).map(member => `${member.displayName}: sisa ${money(remaining(bill.value, member))}`).join('\n')}\nCatatan Danarapi, bukan bukti pembayaran.`); state.notice = 'Ringkasan disalin.'; } catch { error.value = 'Clipboard tidak tersedia. Salin ringkasan dari layar.'; } }
</script>
<template><section v-if="bill" class="bill-detail"><div class="callout peach"><span class="eyebrow">TOTAL TAGIHAN</span><h2><Money :amount="bill.total" /></h2><p>Bagian saya <Money :amount="selfShare(bill)" /> · {{ bill.payer.selfPaid ? 'Saya membayar' : 'Teman membayar' }}</p><span class="pill">{{ billStatus(bill) }}</span></div><ReceiptBillBreakdown :bill="bill" /><h3>Sisa kewajiban</h3><div v-for="member in obligations(bill)" :key="member.id" class="list-row"><span class="avatar peach">{{ member.displayName.charAt(0) }}</span><div class="row-copy"><strong>{{ member.displayName }}</strong><span>{{ remaining(bill, member) === 0n ? 'Lunas' : bill.payer.selfPaid ? 'Belum dibayar teman' : 'Utang saya kepada teman' }}</span></div><Money :amount="remaining(bill, member)" /></div><div class="button-row"><button class="secondary" @click="copy"><Icon name="copy" /> Salin ringkasan</button><button class="secondary" :disabled="!editable" @click="emit('edit', bill)"><Icon name="edit" /> Ubah</button><button class="danger" :disabled="!editable" @click="emit('remove', bill)"><Icon name="trash" /> Hapus</button></div><p v-if="!editable" class="fine-print">Batalkan seluruh kejadian aktif sebelum mengubah struktur atau menghapus tagihan.</p><form class="entry-form" @submit.prevent="save"><h3>Catat pelunasan / keputusan</h3><div class="form-grid"><label>Tindakan<select v-model="action"><option value="settlement">Catat pelunasan</option><option value="resolution">Hapus kewajiban nonkas</option></select></label><label>Peserta<select v-model="memberID" required><option value="" disabled>Pilih peserta</option><option v-for="member in obligations(bill).filter(row => remaining(bill, row) > 0n)" :key="member.id" :value="member.id">{{ member.displayName }}</option></select></label><label>Nominal<MoneyInput v-model="amount" required /></label><label v-if="action === 'settlement'">Akun<select v-model="accountID" required><option v-for="account in state.data.accounts.filter(row => !row.archived)" :key="account.id" :value="account.id">{{ account.name }}</option></select></label><label>Tanggal<input v-model="date" type="date" required></label><label>{{ action === 'resolution' ? 'Alasan (wajib)' : 'Catatan (opsional)' }}<input v-model="reason" :required="action === 'resolution'" maxlength="2000"></label></div><p class="callout sky">{{ action === 'settlement' ? bill.payer.selfPaid ? 'Pelunasan ini hanya mengurangi piutang, bukan pemasukan.' : 'Pelunasan ini hanya mengurangi utang, bukan pengeluaran baru.' : 'Saldo akun tidak berubah. Keputusan nonkas tercatat dalam laporan.' }}</p><p v-if="error || state.error" role="alert" class="error-text">{{ error || state.error }}</p><button class="primary" :disabled="state.saving">{{ state.saving ? 'Menyimpan…' : action === 'settlement' ? 'Catat pelunasan' : 'Hapus kewajiban' }}</button></form><h3>Riwayat pelunasan</h3><p v-if="!bill.settlements.length && !bill.resolutions.length" class="muted">Belum ada pelunasan atau keputusan nonkas.</p><div v-for="event in [...bill.settlements, ...bill.resolutions]" :key="event.id" class="list-row"><div class="row-copy"><strong>{{ event.kind ? 'Penghapusan kewajiban' : 'Pelunasan' }} · {{ bill.members.find(row => row.id === event.memberID)?.displayName }}</strong><span>{{ event.occurredAt.slice(0,10) }} · {{ event.reversed ? 'Dibatalkan' : 'Tercatat' }} {{ event.reason ?? event.note }}</span></div><Money :amount="event.amount" /><button v-if="!event.reversed" class="text-button" :disabled="state.saving" @click="reverse(event.id, event.version, !!event.kind)">Batalkan</button></div><AttachmentPanel kind="bill" :target-i-d="bill.id" /></section></template>
